package br.com.sussmartcare.prehospital.domain; import jakarta.persistence.*; import java.time.*; import java.util.*; @Entity @Table(name="pre_hospital_encounters") public class PreHospitalEncounter{@Id private UUID id;@Column(nullable=false)private UUID patientId;private UUID visitId;@Column(nullable=false)private String ambulanceId;@Column(nullable=false)private UUID destinationFacilityId;private Instant estimatedArrivalAt;@Column(nullable=false)private String status;private String riskLevel;@Column(nullable=false)private Instant createdAt;protected PreHospitalEncounter(){}public PreHospitalEncounter(UUID patient,UUID visit,String ambulance,UUID destination,Instant eta){id=UUID.randomUUID();patientId=patient;visitId=visit;ambulanceId=ambulance;destinationFacilityId=destination;estimatedArrivalAt=eta;status="EN_ROUTE";createdAt=Instant.now();}public void updateEta(Instant eta){estimatedArrivalAt=eta;}public void updateRisk(String risk){riskLevel=risk;}public UUID getId(){return id;}public UUID getPatientId(){return patientId;}public UUID getVisitId(){return visitId;}public String getAmbulanceId(){return ambulanceId;}public UUID getDestinationFacilityId(){return destinationFacilityId;}public Instant getEstimatedArrivalAt(){return estimatedArrivalAt;}public String getStatus(){return status;}public String getRiskLevel(){return riskLevel;}public Instant getCreatedAt(){return createdAt;}}
